package com.example.order.common;

import org.springframework.http.HttpStatus;

public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String detail) {
        super(detail);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }

    public static ApiException validation(String detail) {
        return new ApiException(HttpStatus.BAD_REQUEST, "VALIDATION_ERROR", detail);
    }

    public static ApiException notFound(String code, String detail) {
        return new ApiException(HttpStatus.NOT_FOUND, code, detail);
    }

    public static ApiException conflict(String code, String detail) {
        return new ApiException(HttpStatus.CONFLICT, code, detail);
    }

    public static ApiException invalidState(String detail) {
        return conflict("INVALID_STATE", detail);
    }

    public static ApiException gatewayUnavailable(String detail) {
        return new ApiException(HttpStatus.SERVICE_UNAVAILABLE, "PAYMENT_GATEWAY_UNAVAILABLE", detail);
    }
}
package com.example.order.common;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.MediaType;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import java.util.stream.Collectors;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

/** Every error becomes RFC 9457 application/problem+json with type, title, status, detail, code. */
@RestControllerAdvice
public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Object> handleApi(ApiException e) {
        return problem(e.getStatus(), e.getCode(), e.getMessage(), null);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Object> handleUnexpected(Exception e) {
        log.error("Unexpected error", e);
        return problem(HttpStatus.INTERNAL_SERVER_ERROR, "INTERNAL_ERROR", "Unexpected server error", null);
    }

    /** Spring MVC's own exceptions (parse errors, missing params, type mismatch, 404/405/415 ...). */
    @Override
    protected ResponseEntity<Object> handleExceptionInternal(Exception ex, Object body, HttpHeaders headers,
            HttpStatusCode statusCode, WebRequest request) {
        String detail = null;
        if (ex instanceof MethodArgumentNotValidException manv) {
            detail = manv.getBindingResult().getFieldErrors().stream()
                    .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
                    .collect(Collectors.joining(", "));
        } else if (body instanceof ProblemDetail pd) {
            detail = pd.getDetail();
        }
        if (detail == null || detail.isBlank()) {
            detail = ex.getMessage() != null ? ex.getMessage() : "Request failed";
        }
        String code = statusCode.value() == 400 ? "VALIDATION_ERROR" : codeFor(statusCode);
        return problem(statusCode, code, detail, headers);
    }

    private static String codeFor(HttpStatusCode statusCode) {
        HttpStatus s = HttpStatus.resolve(statusCode.value());
        return s != null ? s.name() : "ERROR";
    }

    private static ResponseEntity<Object> problem(HttpStatusCode status, String code, String detail,
            HttpHeaders headers) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
        HttpStatus resolved = HttpStatus.resolve(status.value());
        pd.setTitle(resolved != null ? resolved.getReasonPhrase() : "Error");
        pd.setProperty("code", code);
        HttpHeaders out = new HttpHeaders();
        if (headers != null) {
            out.putAll(headers);
        }
        out.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
        return new ResponseEntity<>(pd, out, status);
    }
}
package com.example.order.common;

import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.time.temporal.ChronoUnit;

/** PostgreSQL timestamptz has microsecond precision; keep every timestamp at that precision in UTC. */
public final class Times {

    private Times() {
    }

    public static OffsetDateTime now() {
        return Instant.now().truncatedTo(ChronoUnit.MICROS).atOffset(ZoneOffset.UTC);
    }

    public static OffsetDateTime normalize(OffsetDateTime t) {
        return t.toInstant().truncatedTo(ChronoUnit.MICROS).atOffset(ZoneOffset.UTC);
    }

    public static long toEpochMicros(OffsetDateTime t) {
        Instant i = t.toInstant();
        return Math.addExact(Math.multiplyExact(i.getEpochSecond(), 1_000_000L), i.getNano() / 1_000L);
    }

    public static OffsetDateTime fromEpochMicros(long micros) {
        return Instant.EPOCH.plus(micros, ChronoUnit.MICROS).atOffset(ZoneOffset.UTC);
    }
}
package com.example.order.idempotency;

import com.example.order.common.ApiException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.List;
import java.util.Optional;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * Idempotency-Key store (R4). A key is claimed by inserting an IN_PROGRESS row in its own (auto-committed)
 * statement; the business transaction turns it into DONE with the response snapshot; failures delete the row so the
 * same request can be retried (only 2xx responses are stored).
 */
@Service
public class IdempotencyService {

    public static final String SCOPE_CREATE_ORDER = "CREATE_ORDER";
    public static final String SCOPE_PAY = "PAY";

    public record StoredResponse(int status, String body, String location) {
    }

    private record Row(String fingerprint, String state, Integer status, String body, String location) {
    }

    private final JdbcTemplate jdbc;

    public IdempotencyService(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * @return empty when this caller now owns the key and must process the request; otherwise the stored response
     * to replay. Throws 422 on fingerprint mismatch and 409 while another request with the key is in flight.
     */
    public Optional<StoredResponse> begin(String scope, String key, String fingerprint) {
        while (true) {
            int inserted = jdbc.update("INSERT INTO idempotency_keys (scope, idem_key, fingerprint, state) "
                    + "VALUES (?, ?, ?, 'IN_PROGRESS') ON CONFLICT (scope, idem_key) DO NOTHING",
                    scope, key, fingerprint);
            if (inserted == 1) {
                return Optional.empty();
            }
            List<Row> rows = jdbc.query("SELECT fingerprint, state, response_status, response_body, location "
                            + "FROM idempotency_keys WHERE scope = ? AND idem_key = ?",
                    (rs, i) -> new Row(rs.getString(1), rs.getString(2), (Integer) rs.getObject(3, Integer.class),
                            rs.getString(4), rs.getString(5)),
                    scope, key);
            if (rows.isEmpty()) {
                continue; // the previous holder failed and released the key; try to claim it again
            }
            Row row = rows.get(0);
            if (!row.fingerprint().equals(fingerprint)) {
                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "IDEMPOTENCY_KEY_MISMATCH",
                        "Idempotency-Key was already used for a different request");
            }
            if ("DONE".equals(row.state())) {
                return Optional.of(new StoredResponse(row.status(), row.body(), row.location()));
            }
            throw ApiException.conflict("IDEMPOTENCY_IN_PROGRESS",
                    "a request with this Idempotency-Key is still being processed");
        }
    }

    /** Called inside the business transaction so the snapshot commits atomically with the state change. */
    public void complete(String scope, String key, int status, String body, String location) {
        jdbc.update("UPDATE idempotency_keys SET state = 'DONE', response_status = ?, response_body = ?, "
                + "location = ? WHERE scope = ? AND idem_key = ?", status, body, location, scope, key);
    }

    public void release(String scope, String key) {
        jdbc.update("DELETE FROM idempotency_keys WHERE scope = ? AND idem_key = ? AND state = 'IN_PROGRESS'",
                scope, key);
    }

    public static String fingerprint(String canonical) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(md.digest(canonical.getBytes(StandardCharsets.UTF_8)));
        } catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }
}
package com.example.order.payment;

import com.example.order.common.ApiException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * External PG. Any 5xx, connection failure, 2-second timeout (whole exchange) or unusable response is reported as
 * 503 PAYMENT_GATEWAY_UNAVAILABLE.
 */
@Component
public class PaymentGatewayClient {

    private static final Logger log = LoggerFactory.getLogger(PaymentGatewayClient.class);
    static final Duration TIMEOUT = Duration.ofSeconds(2);

    public enum PaymentStatus { APPROVED, DECLINED }

    public record PaymentResult(String paymentId, PaymentStatus status) {
    }

    private final String baseUrl;
    private final ObjectMapper mapper;
    private final HttpClient http = HttpClient.newBuilder()
            .version(HttpClient.Version.HTTP_1_1)
            .connectTimeout(TIMEOUT)
            .build();

    public PaymentGatewayClient(@Value("${app.payment-gateway-url}") String baseUrl, ObjectMapper mapper) {
        this.baseUrl = baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
        this.mapper = mapper;
    }

    public PaymentResult pay(long orderId, long amount, String cardToken, String idempotencyKey) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("orderId", orderId);
        body.put("amount", amount);
        body.put("cardToken", cardToken);
        HttpRequest req;
        try {
            req = HttpRequest.newBuilder(URI.create(baseUrl + "/v1/payments"))
                    .timeout(TIMEOUT)
                    .header("Content-Type", "application/json")
                    .header("Accept", "application/json")
                    .header("Idempotency-Key", idempotencyKey)
                    .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body)))
                    .build();
        } catch (Exception e) {
            throw ApiException.gatewayUnavailable("payment gateway request could not be built");
        }
        JsonNode json = exchange(req);
        String status = json.path("status").asText("");
        String paymentId = json.path("paymentId").isMissingNode() || json.path("paymentId").isNull()
                ? null : json.path("paymentId").asText();
        return switch (status) {
            case "APPROVED" -> new PaymentResult(paymentId, PaymentStatus.APPROVED);
            case "DECLINED" -> new PaymentResult(paymentId, PaymentStatus.DECLINED);
            default -> throw ApiException.gatewayUnavailable("payment gateway returned unknown status");
        };
    }

    public void refund(String paymentId) {
        HttpRequest req = HttpRequest.newBuilder(
                        URI.create(baseUrl + "/v1/payments/" + encodePath(paymentId) + "/refund"))
                .timeout(TIMEOUT)
                .header("Accept", "application/json")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build();
        JsonNode json = exchange(req);
        if (!"REFUNDED".equals(json.path("status").asText(""))) {
            throw ApiException.gatewayUnavailable("payment gateway did not confirm the refund");
        }
    }

    private JsonNode exchange(HttpRequest req) {
        CompletableFuture<HttpResponse<String>> future = http.sendAsync(req, HttpResponse.BodyHandlers.ofString());
        HttpResponse<String> res;
        try {
            res = future.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
        } catch (InterruptedException e) {
            future.cancel(true);
            Thread.currentThread().interrupt();
            throw ApiException.gatewayUnavailable("payment gateway call interrupted");
        } catch (Exception e) {
            future.cancel(true);
            log.warn("payment gateway call failed: {} {}", req.uri(), e.toString());
            throw ApiException.gatewayUnavailable("payment gateway is unavailable");
        }
        if (res.statusCode() / 100 != 2) {
            log.warn("payment gateway returned {} for {}", res.statusCode(), req.uri());
            throw ApiException.gatewayUnavailable("payment gateway responded with status " + res.statusCode());
        }
        try {
            return mapper.readTree(res.body());
        } catch (Exception e) {
            throw ApiException.gatewayUnavailable("payment gateway returned an unreadable response");
        }
    }

    private static String encodePath(String segment) {
        return java.net.URLEncoder.encode(segment, java.nio.charset.StandardCharsets.UTF_8).replace("+", "%20");
    }
}

