/**
 * Idempotency-Key store (R4). A key is claimed by inserting an IN_PROGRESS row in its own (auto-committed)
 * statement; the business transaction turns it into DONE with the response snapshot; failures delete the row so the
 * same request can be retried (only 2xx responses are stored).
 */
@Service
public class IdempotencyService {

    public static final String SCOPE_CREATE_ORDER = "CREATE_ORDER";
    public static final String SCOPE_PAY = "PAY";

    public record StoredResponse(int status, String body, String location) {
    }

    private record Row(String fingerprint, String state, Integer status, String body, String location) {
    }

    private final JdbcTemplate jdbc;

    public IdempotencyService(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * @return empty when this caller now owns the key and must process the request; otherwise the stored response
     * to replay. Throws 422 on fingerprint mismatch and 409 while another request with the key is in flight.
     */
    public Optional<StoredResponse> begin(String scope, String key, String fingerprint) {
        while (true) {
            int inserted = jdbc.update("INSERT INTO idempotency_keys (scope, idem_key, fingerprint, state) "
                    + "VALUES (?, ?, ?, 'IN_PROGRESS') ON CONFLICT (scope, idem_key) DO NOTHING",
                    scope, key, fingerprint);
            if (inserted == 1) {
                return Optional.empty();
            }
            List<Row> rows = jdbc.query("SELECT fingerprint, state, response_status, response_body, location "
                            + "FROM idempotency_keys WHERE scope = ? AND idem_key = ?",
                    (rs, i) -> new Row(rs.getString(1), rs.getString(2), (Integer) rs.getObject(3, Integer.class),
                            rs.getString(4), rs.getString(5)),
                    scope, key);
            if (rows.isEmpty()) {
                continue; // the previous holder failed and released the key; try to claim it again
            }
            Row row = rows.get(0);
            if (!row.fingerprint().equals(fingerprint)) {
                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "IDEMPOTENCY_KEY_MISMATCH",
                        "Idempotency-Key was already used for a different request");
            }
            if ("DONE".equals(row.state())) {
                return Optional.of(new StoredResponse(row.status(), row.body(), row.location()));
            }
            throw ApiException.conflict("IDEMPOTENCY_IN_PROGRESS",
                    "a request with this Idempotency-Key is still being processed");
        }
    }

    /** Called inside the business transaction so the snapshot commits atomically with the state change. */
    public void complete(String scope, String key, int status, String body, String location) {
        jdbc.update("UPDATE idempotency_keys SET state = 'DONE', response_status = ?, response_body = ?, "
                + "location = ? WHERE scope = ? AND idem_key = ?", status, body, location, scope, key);
    }

    public void release(String scope, String key) {
        jdbc.update("DELETE FROM idempotency_keys WHERE scope = ? AND idem_key = ? AND state = 'IN_PROGRESS'",
                scope, key);
    }

    public static String fingerprint(String canonical) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(md.digest(canonical.getBytes(StandardCharsets.UTF_8)));
        } catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }
}
package com.example.order.payment;

import com.example.order.common.ApiException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * External PG. Any 5xx, connection failure, 2-second timeout (whole exchange) or unusable response is reported as
 * 503 PAYMENT_GATEWAY_UNAVAILABLE.
 */
@Component
public class PaymentGatewayClient {

    private static final Logger log = LoggerFactory.getLogger(PaymentGatewayClient.class);
    static final Duration TIMEOUT = Duration.ofSeconds(2);

    public enum PaymentStatus { APPROVED, DECLINED }

    public record PaymentResult(String paymentId, PaymentStatus status) {
    }

    private final String baseUrl;
    private final ObjectMapper mapper;
    private final HttpClient http = HttpClient.newBuilder()
            .version(HttpClient.Version.HTTP_1_1)
            .connectTimeout(TIMEOUT)
            .build();

    public PaymentGatewayClient(@Value("${app.payment-gateway-url}") String baseUrl, ObjectMapper mapper) {
        this.baseUrl = baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
        this.mapper = mapper;
    }

    public PaymentResult pay(long orderId, long amount, String cardToken, String idempotencyKey) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("orderId", orderId);
        body.put("amount", amount);
        body.put("cardToken", cardToken);
        HttpRequest req;
        try {
            req = HttpRequest.newBuilder(URI.create(baseUrl + "/v1/payments"))
                    .timeout(TIMEOUT)
                    .header("Content-Type", "application/json")
                    .header("Accept", "application/json")
                    .header("Idempotency-Key", idempotencyKey)
                    .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body)))
                    .build();
        } catch (Exception e) {
            throw ApiException.gatewayUnavailable("payment gateway request could not be built");
        }
        JsonNode json = exchange(req);
        String status = json.path("status").asText("");
        String paymentId = json.path("paymentId").isMissingNode() || json.path("paymentId").isNull()
                ? null : json.path("paymentId").asText();
        return switch (status) {
            case "APPROVED" -> new PaymentResult(paymentId, PaymentStatus.APPROVED);
            case "DECLINED" -> new PaymentResult(paymentId, PaymentStatus.DECLINED);
            default -> throw ApiException.gatewayUnavailable("payment gateway returned unknown status");
        };
    }

    public void refund(String paymentId) {
        HttpRequest req = HttpRequest.newBuilder(
                        URI.create(baseUrl + "/v1/payments/" + encodePath(paymentId) + "/refund"))
                .timeout(TIMEOUT)
                .header("Accept", "application/json")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build();
        JsonNode json = exchange(req);
        if (!"REFUNDED".equals(json.path("status").asText(""))) {
            throw ApiException.gatewayUnavailable("payment gateway did not confirm the refund");
        }
    }

    private JsonNode exchange(HttpRequest req) {
        CompletableFuture<HttpResponse<String>> future = http.sendAsync(req, HttpResponse.BodyHandlers.ofString());
        HttpResponse<String> res;
        try {
            res = future.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
        } catch (InterruptedException e) {
            future.cancel(true);
            Thread.currentThread().interrupt();
            throw ApiException.gatewayUnavailable("payment gateway call interrupted");
        } catch (Exception e) {
            future.cancel(true);
            log.warn("payment gateway call failed: {} {}", req.uri(), e.toString());
            throw ApiException.gatewayUnavailable("payment gateway is unavailable");
        }
        if (res.statusCode() / 100 != 2) {
            log.warn("payment gateway returned {} for {}", res.statusCode(), req.uri());
            throw ApiException.gatewayUnavailable("payment gateway responded with status " + res.statusCode());
        }
        try {
            return mapper.readTree(res.body());
        } catch (Exception e) {
            throw ApiException.gatewayUnavailable("payment gateway returned an unreadable response");
        }
    }

    private static String encodePath(String segment) {
        return java.net.URLEncoder.encode(segment, java.nio.charset.StandardCharsets.UTF_8).replace("+", "%20");
    }
}

