package com.example.order.order;

import java.time.OffsetDateTime;
import java.util.List;

public record Order(long id, String userId, OrderStatus status, String couponCode, long subtotal, long discount,
        long totalPrice, OffsetDateTime createdAt, OffsetDateTime expiresAt, OffsetDateTime paidAt,
        String paymentId, List<Item> items) {

    public record Item(long productId, long quantity, long unitPrice) {
    }

    public Order withItems(List<Item> newItems) {
        return new Order(id, userId, status, couponCode, subtotal, discount, totalPrice, createdAt, expiresAt,
                paidAt, paymentId, newItems);
    }
}
package com.example.order.order;

public enum OrderStatus {
    PENDING_PAYMENT, PAID, SHIPPED, DELIVERED, PAYMENT_FAILED, EXPIRED, CANCELLED, REFUNDED
}
package com.example.order.order;

import java.time.OffsetDateTime;
import java.util.List;

/** R3.5 representation. */
public record OrderResponse(long id, String userId, String status, List<ItemResponse> items, String couponCode,
        long subtotal, long discount, long totalPrice, OffsetDateTime createdAt, OffsetDateTime expiresAt,
        OffsetDateTime paidAt) {

    public record ItemResponse(long productId, long quantity, long unitPrice) {
    }

    public static OrderResponse from(Order o) {
        return new OrderResponse(o.id(), o.userId(), o.status().name(),
                o.items().stream().map(i -> new ItemResponse(i.productId(), i.quantity(), i.unitPrice())).toList(),
                o.couponCode(), o.subtotal(), o.discount(), o.totalPrice(), o.createdAt(), o.expiresAt(),
                o.paidAt());
    }
}
package com.example.order.order;

import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class OrderRepository {

    private static final String COLS = "id, user_id, status, coupon_code, subtotal, discount, total_price, "
            + "created_at, expires_at, paid_at, payment_id";

    private static final RowMapper<Order> MAPPER = (rs, i) -> new Order(
            rs.getLong("id"), rs.getString("user_id"), OrderStatus.valueOf(rs.getString("status")),
            rs.getString("coupon_code"), rs.getLong("subtotal"), rs.getLong("discount"), rs.getLong("total_price"),
            rs.getObject("created_at", OffsetDateTime.class), rs.getObject("expires_at", OffsetDateTime.class),
            rs.getObject("paid_at", OffsetDateTime.class), rs.getString("payment_id"), List.of());

    private final JdbcTemplate jdbc;
    private final NamedParameterJdbcTemplate named;

    public OrderRepository(JdbcTemplate jdbc, NamedParameterJdbcTemplate named) {
        this.jdbc = jdbc;
        this.named = named;
    }

    public long insert(String userId, String couponCode, long subtotal, long discount, long totalPrice,
            OffsetDateTime createdAt, OffsetDateTime expiresAt, List<Order.Item> items) {
        Long id = jdbc.queryForObject("INSERT INTO orders (user_id, status, coupon_code, subtotal, discount, "
                        + "total_price, created_at, expires_at) VALUES (?, 'PENDING_PAYMENT', ?, ?, ?, ?, ?, ?) "
                        + "RETURNING id",
                Long.class, userId, couponCode, subtotal, discount, totalPrice, createdAt, expiresAt);
        int line = 0;
        for (Order.Item item : items) {
            jdbc.update("INSERT INTO order_items (order_id, line_no, product_id, quantity, unit_price) "
                    + "VALUES (?, ?, ?, ?, ?)", id, line++, item.productId(), item.quantity(), item.unitPrice());
        }
        return id;
    }

    public Optional<Order> find(long id) {
        return one("SELECT " + COLS + " FROM orders WHERE id = ?", id);
    }

    public Optional<Order> lock(long id) {
        return one("SELECT " + COLS + " FROM orders WHERE id = ? FOR UPDATE", id);
    }

    private Optional<Order> one(String sql, long id) {
        List<Order> rows = jdbc.query(sql, MAPPER, id);
        if (rows.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(withItems(rows).get(0));
    }

    /** Ids of PENDING_PAYMENT orders whose expiresAt has passed, locked; rows locked by others are skipped. */
    public List<Order> lockExpired(OffsetDateTime now, int limit) {
        List<Order> rows = jdbc.query("SELECT " + COLS + " FROM orders WHERE status = 'PENDING_PAYMENT' "
                + "AND expires_at <= ? ORDER BY id LIMIT ? FOR UPDATE SKIP LOCKED", MAPPER, now, limit);
        return withItems(rows);
    }

    public void updateStatus(long id, OrderStatus status) {
        jdbc.update("UPDATE orders SET status = ? WHERE id = ?", status.name(), id);
    }

    public void markPaid(long id, OffsetDateTime paidAt, String paymentId) {
        jdbc.update("UPDATE orders SET status = 'PAID', paid_at = ?, payment_id = ? WHERE id = ?",
                paidAt, paymentId, id);
    }

    /** R2.5/R2.6: orders of this user that are currently using the coupon. */
    public boolean userHasActiveCouponOrder(String userId, String couponCode) {
        Boolean b = jdbc.queryForObject("SELECT EXISTS (SELECT 1 FROM orders WHERE user_id = ? AND coupon_code = ? "
                        + "AND status IN ('PENDING_PAYMENT', 'PAID', 'SHIPPED', 'DELIVERED'))",
                Boolean.class, userId, couponCode);
        return Boolean.TRUE.equals(b);
    }

    /** Keyset page ordered by (created_at DESC, id DESC); fetches limit rows. */
    public List<Order> page(String userId, OrderStatus status, OffsetDateTime afterCreatedAt, Long afterId,
            int limit) {
        StringBuilder sql = new StringBuilder("SELECT " + COLS + " FROM orders WHERE 1 = 1");
        MapSqlParameterSource p = new MapSqlParameterSource();
        if (userId != null) {
            sql.append(" AND user_id = :userId");
            p.addValue("userId", userId);
        }
        if (status != null) {
            sql.append(" AND status = :status");
            p.addValue("status", status.name());
        }
        if (afterCreatedAt != null) {
            sql.append(" AND (created_at, id) < (:cAt, :cId)");
            p.addValue("cAt", afterCreatedAt);
            p.addValue("cId", afterId);
        }
        sql.append(" ORDER BY created_at DESC, id DESC LIMIT :limit");
        p.addValue("limit", limit);
        return withItems(named.query(sql.toString(), p, MAPPER));
    }

    private List<Order> withItems(List<Order> orders) {
        if (orders.isEmpty()) {
            return orders;
        }
        Map<Long, List<Order.Item>> byOrder = new LinkedHashMap<>();
        Collection<Long> ids = orders.stream().map(Order::id).toList();
        for (Long id : ids) {
            byOrder.put(id, new ArrayList<>());
        }
        named.query("SELECT order_id, product_id, quantity, unit_price FROM order_items "
                        + "WHERE order_id IN (:ids) ORDER BY order_id, line_no",
                new MapSqlParameterSource("ids", ids),
                rs -> {
                    byOrder.get(rs.getLong("order_id")).add(new Order.Item(rs.getLong("product_id"),
                            rs.getLong("quantity"), rs.getLong("unit_price")));
                });
        return orders.stream().map(o -> o.withItems(List.copyOf(byOrder.get(o.id())))).toList();
    }
}
package com.example.order.order;

import com.example.order.coupon.CouponRepository;
import com.example.order.product.ProductRepository;
import java.util.Comparator;
import org.springframework.stereotype.Component;

/**
 * Stock/coupon side effects of order transitions. Product rows are always touched in ascending id order and the coupon
 * row last, matching the lock order used by order creation, so concurrent transitions cannot deadlock.
 */
@Component
public class ReservationReleaser {

    private final ProductRepository products;
    private final CouponRepository coupons;

    public ReservationReleaser(ProductRepository products, CouponRepository coupons) {
        this.products = products;
        this.coupons = coupons;
    }

    /** PENDING_PAYMENT -> CANCELLED / EXPIRED / PAYMENT_FAILED: drop reservations, give the coupon use back. */
    public void releaseReservation(Order order) {
        order.items().stream().sorted(Comparator.comparingLong(Order.Item::productId))
                .forEach(i -> products.addReserved(i.productId(), -i.quantity()));
        restoreCoupon(order);
    }

    /** PENDING_PAYMENT -> PAID: reserved units are sold. */
    public void consumeReservation(Order order) {
        order.items().stream().sorted(Comparator.comparingLong(Order.Item::productId))
                .forEach(i -> products.consumeReserved(i.productId(), i.quantity()));
    }

    /** PAID -> REFUNDED: units go back to stock, coupon use is restored. */
    public void returnStock(Order order) {
        order.items().stream().sorted(Comparator.comparingLong(Order.Item::productId))
                .forEach(i -> products.addStock(i.productId(), i.quantity()));
        restoreCoupon(order);
    }

    private void restoreCoupon(Order order) {
        if (order.couponCode() != null) {
            coupons.addUsed(order.couponCode(), -1);
        }
    }
}
package com.example.order.order;

import com.example.order.common.Times;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/**
 * R6: PENDING_PAYMENT orders past expiresAt become EXPIRED. A sweeper runs every 500 ms, and reads call
 * {@link #expireDue()} first so the change is visible as soon as possible. Each order is expired in its own
 * transaction; rows locked by a concurrent payment/cancel are skipped (that path re-checks expiry itself).
 */
@Service
public class ExpiryService {

    private static final Logger log = LoggerFactory.getLogger(ExpiryService.class);

    private final OrderRepository orders;
    private final ReservationReleaser releaser;
    private final TransactionTemplate tx;

    public ExpiryService(OrderRepository orders, ReservationReleaser releaser, PlatformTransactionManager tm) {
        this.orders = orders;
        this.releaser = releaser;
        this.tx = new TransactionTemplate(tm);
        this.tx.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
    }

    @Scheduled(fixedDelay = 500, initialDelay = 500)
    public void sweep() {
        try {
            expireDue();
        } catch (Exception e) {
            log.warn("expiry sweep failed", e);
        }
    }

    public void expireDue() {
        while (Boolean.TRUE.equals(tx.execute(s -> expireOne()))) {
            // keep going until nothing is due
        }
    }

    private boolean expireOne() {
        List<Order> due = orders.lockExpired(Times.now(), 1);
        if (due.isEmpty()) {
            return false;
        }
        expire(due.get(0));
        return true;
    }

    /** Caller must hold the order row lock and be inside a transaction. */
    public void expire(Order order) {
        releaser.releaseReservation(order);
        orders.updateStatus(order.id(), OrderStatus.EXPIRED);
    }
}
package com.example.order.order;

import com.example.order.common.ApiException;
import com.example.order.idempotency.IdempotencyService;
import com.example.order.idempotency.IdempotencyService.StoredResponse;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.net.URI;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.function.Supplier;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final OrderService service;
    private final IdempotencyService idempotency;
    private final ObjectMapper mapper;

    public OrderController(OrderService service, IdempotencyService idempotency, ObjectMapper mapper) {
        this.service = service;
        this.idempotency = idempotency;
        this.mapper = mapper;
    }

    public record ItemRequest(@NotNull Long productId, @NotNull @Min(1) @Max(1000) Long quantity) {
    }

    public record CreateOrderRequest(@NotNull @Size(min = 1, max = 20) List<@NotNull @Valid ItemRequest> items,
            String couponCode) {
    }

    public record PayRequest(@NotBlank String cardToken) {
    }

    @PostMapping
    public ResponseEntity<String> create(
            @RequestHeader(value = "X-User-Id", required = false) String userId,
            @RequestHeader(value = "Idempotency-Key", required = false) String idemKey,
            @Valid @RequestBody CreateOrderRequest req) {
        // 400
        if (userId == null || userId.isBlank() || userId.length() > 50) {
            throw ApiException.validation("X-User-Id header is required (1-50 non-blank characters)");
        }
        validateIdempotencyKey(idemKey);
        Set<Long> seen = new HashSet<>();
        for (ItemRequest item : req.items()) {
            if (!seen.add(item.productId())) {
                throw ApiException.validation("duplicate productId " + item.productId());
            }
        }
        List<OrderService.ItemCommand> items = req.items().stream()
                .map(i -> new OrderService.ItemCommand(i.productId(), i.quantity())).toList();

        // same request = same X-User-Id + same body
        Map<String, Object> canonical = new LinkedHashMap<>();
        canonical.put("userId", userId);
        canonical.put("items", items.stream().map(i -> List.of(i.productId(), i.quantity())).toList());
        canonical.put("couponCode", req.couponCode());
        String fp = IdempotencyService.fingerprint(toJson(canonical));

        return idempotent(IdempotencyService.SCOPE_CREATE_ORDER, idemKey, fp, () -> {
            OrderService.Written w = service.create(userId, items, req.couponCode(), idemKey);
            return ResponseEntity.created(URI.create(OrderService.location(w.orderId())))
                    .contentType(MediaType.APPLICATION_JSON).body(w.body());
        });
    }

    @PostMapping("/{id}/pay")
    public ResponseEntity<String> pay(@PathVariable long id,
            @RequestHeader(value = "Idempotency-Key", required = false) String idemKey,
            @Valid @RequestBody PayRequest req) {
        validateIdempotencyKey(idemKey);
        // same request = same path + same body
        Map<String, Object> canonical = new LinkedHashMap<>();
        canonical.put("orderId", id);
        canonical.put("cardToken", req.cardToken());
        String fp = IdempotencyService.fingerprint(toJson(canonical));

        return idempotent(IdempotencyService.SCOPE_PAY, idemKey, fp, () -> {
            OrderService.Written w = service.pay(id, req.cardToken(), idemKey);
            return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).body(w.body());
        });
    }

    @PostMapping("/{id}/cancel")
    public ResponseEntity<String> cancel(@PathVariable long id) {
        return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).body(service.cancel(id));
    }

    @PostMapping("/{id}/ship")
    public ResponseEntity<String> ship(@PathVariable long id) {
        return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).body(service.ship(id));
    }

    @PostMapping("/{id}/deliver")
    public ResponseEntity<String> deliver(@PathVariable long id) {
        return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).body(service.deliver(id));
    }

    @GetMapping("/{id}")
    public OrderResponse get(@PathVariable long id) {
        return service.get(id);
    }

    @GetMapping
    public OrderService.Page list(@RequestParam(required = false) String userId,
            @RequestParam(required = false) String status,
            @RequestParam(required = false) String size,
            @RequestParam(required = false) String cursor) {
        OrderStatus statusFilter = null;
        if (status != null) {
            try {
                statusFilter = OrderStatus.valueOf(status);
            } catch (IllegalArgumentException e) {
                throw ApiException.validation("unknown status " + status);
            }
        }
        int pageSize = 20;
        if (size != null) {
            try {
                pageSize = Integer.parseInt(size.trim());
            } catch (NumberFormatException e) {
                throw ApiException.validation("size must be an integer between 1 and 100");
            }
            if (pageSize < 1 || pageSize > 100) {
                throw ApiException.validation("size must be between 1 and 100");
            }
        }
        OrderCursor decoded = (cursor == null || cursor.isEmpty()) ? null : OrderCursor.decode(cursor);
        String userFilter = (userId == null || userId.isEmpty()) ? null : userId;
        return service.list(userFilter, statusFilter, pageSize, decoded);
    }

    private ResponseEntity<String> idempotent(String scope, String key, String fingerprint,
            Supplier<ResponseEntity<String>> action) {
        Optional<StoredResponse> stored = idempotency.begin(scope, key, fingerprint);
        if (stored.isPresent()) {
            StoredResponse r = stored.get();
            ResponseEntity.BodyBuilder b = ResponseEntity.status(r.status()).contentType(MediaType.APPLICATION_JSON);
            if (r.location() != null) {
                b.location(URI.create(r.location()));
            }
            return b.body(r.body());
        }
        try {
            return action.get();
        } catch (RuntimeException | Error e) {
            idempotency.release(scope, key);
            throw e;
        }
    }

    private static void validateIdempotencyKey(String key) {
        if (key == null || key.isEmpty() || key.length() > 64) {
            throw ApiException.validation("Idempotency-Key header is required (1-64 characters)");
        }
    }

    private String toJson(Object o) {
        try {
            return mapper.writeValueAsString(o);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException(e);
        }
    }
}

